/* funnel-training.js — behaviour for the FUNNEL TRAINING page component.
 *
 * Generated by references/funnel-training-page-v2/_publish.mjs — EDIT THAT.
 *
 * Five jobs: inline icons, the three-part tab/accordion controller, the
 * per-strategy card accordion, copy-to-clipboard on the DM scripts, the
 * click-to-load video facade, and scroll reveal. One guard so two blocks on one
 * page cannot double-bind.
 */
if (!window.__sharkFunnelTraining) {
  window.__sharkFunnelTraining = true;
(function () {
  var NS = "http://www.w3.org/2000/svg";
  var I = {
    play:   "M7 4.5v15l13-7.5z",
    funnel: "M3 4h18l-7 8v7l-4 2v-9z",
    info:   "M12 21a9 9 0 100-18 9 9 0 000 18zM12 11v5M12 7.6v.4",
    eye:    "M2.5 12S6 5.8 12 5.8 21.5 12 21.5 12 18 18.2 12 18.2 2.5 12 2.5 12zM12 14.8a2.8 2.8 0 100-5.6 2.8 2.8 0 000 5.6z",
    chat:   "M20.5 12.4c0 4-3.8 7.2-8.5 7.2a10 10 0 01-2.6-.34L4 21l1.2-3.4A6.9 6.9 0 013.5 12.4c0-4 3.8-7.2 8.5-7.2s8.5 3.2 8.5 7.2z",
    image:  "M4 5h16v14H4zM4 16l4.5-4.5 3.5 3.5 3-3L20 16M9 9.5a1 1 0 100-2 1 1 0 000 2z",
    school: "M12 4l9 4.5-9 4.5-9-4.5zM7 11v4.6c0 1.4 2.2 2.4 5 2.4s5-1 5-2.4V11",
    book:   "M4.5 5.2A1.7 1.7 0 016.2 3.5H19v13.2H6.2a1.7 1.7 0 00-1.7 1.7zM4.5 18.4a1.7 1.7 0 001.7 1.7H19v-3.4M8.2 7.6h6.6M8.2 11h4.4",
    mega:   "M4 10.2v3.6a1 1 0 001 1h2.2l7.3 3.9V5.3L7.2 9.2H5a1 1 0 00-1 1zM18.4 9.4a3.6 3.6 0 010 5.2M7.2 15.2V19a1 1 0 001 1h1.4a1 1 0 001-1v-2.2",
    target: "M12 21a9 9 0 100-18 9 9 0 000 18zM12 16.5a4.5 4.5 0 100-9 4.5 4.5 0 000 9zM12 13.2a1.2 1.2 0 100-2.4 1.2 1.2 0 000 2.4z",
    arrow:  "M5 12h14M13 6l6 6-6 6",
    ext:    "M14 4h6v6M20 4l-9 9M18 14v5a1 1 0 01-1 1H5a1 1 0 01-1-1V7a1 1 0 011-1h5",
    chev:   "M6 9.2l6 6 6-6",
    bolt:   "M13.2 3 5.5 13.4h5.4l-.9 7.6 7.7-10.4h-5.4z",
    down:   "M12 4.8v13.4M6.6 12.8l5.4 5.4 5.4-5.4",
    copy:   "M9 9V5.5A1.5 1.5 0 0110.5 4h8A1.5 1.5 0 0120 5.5v8a1.5 1.5 0 01-1.5 1.5H15M5.5 9h8A1.5 1.5 0 0115 10.5v8a1.5 1.5 0 01-1.5 1.5h-8A1.5 1.5 0 014 18.5v-8A1.5 1.5 0 015.5 9z"
  };

  function icon(name) {
    var d = I[name];
    if (!d) return null;
    var svg = document.createElementNS(NS, "svg");
    svg.setAttribute("viewBox", "0 0 24 24");
    svg.setAttribute("fill", "none");
    svg.setAttribute("stroke", "currentColor");
    svg.setAttribute("stroke-width", "1.7");
    svg.setAttribute("stroke-linecap", "round");
    svg.setAttribute("stroke-linejoin", "round");
    svg.setAttribute("aria-hidden", "true");
    var p = document.createElementNS(NS, "path");
    p.setAttribute("d", d);
    if (name === "play") { p.setAttribute("fill", "currentColor"); svg.setAttribute("stroke-width", "1"); }
    svg.appendChild(p);
    return svg;
  }

  var els = document.querySelectorAll("[data-sk-icon]");
  for (var i = 0; i < els.length; i++) {
    if (els[i].firstElementChild) continue;
    var s = icon(els[i].getAttribute("data-sk-icon"));
    if (s) els[i].appendChild(s);
  }

  /* copy a script to the clipboard, with the placeholders left in as (name) etc
     so the rep can see what still needs swapping in their own thread */
  function plain(node) {
    var out = [];
    node.querySelectorAll("p").forEach(function (p) {
      var t = "";
      p.childNodes.forEach(function (n) {
        if (n.nodeType === 3) t += n.nodeValue;
        else if (n.classList && n.classList.contains("sk-var")) t += "(" + n.textContent + ")";
        else t += n.textContent;
      });
      out.push(t.replace(/\s+/g, " ").trim());
    });
    return out.join("\n\n");
  }

  document.querySelectorAll("[data-copy]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      var body = btn.closest(".sk-msg").querySelector(".sk-msg-body");
      var label = btn.querySelector("span");
      navigator.clipboard.writeText(plain(body)).then(function () {
        btn.setAttribute("data-done", "true");
        label.textContent = "Copied";
        setTimeout(function () {
          btn.removeAttribute("data-done");
          label.textContent = "Copy";
        }, 1800);
      });
    });
  });


  /* ---- the three parts: tabs on desktop, accordion on a phone ----
     One controller for both. The strip is BUILT from the accordion headers, so
     the two can never disagree about what a part is called. Which mode is live
     is read from whether the strip is displayed, i.e. from CSS, so the
     breakpoint lives in one place. */
  var openPart = null;   /* set below; lets any control drive the tab strip */
  var tabsRoot = document.querySelector("[data-tabs]");
  if (tabsRoot) {
    var strip  = tabsRoot.querySelector(".sk-tabstrip");
    var panels = [].slice.call(tabsRoot.querySelectorAll(".sk-panel"));


    /* ---- the bottom bar (phone only) ----
       Joe's requirement: a rep must SEE that this page carries training, not
       discover it by scrolling. The three parts are the page, so the bar is
       three equal segments, always on screen, and tapping one opens that part.
       Built from the accordion headers like the desktop strip is, so the two
       navigations can never disagree about what a part is or what it is called;
       the short label rides on the header as data-nav, because "How to Approach
       & Follow Up With Leads" cannot fit in a third of a phone. */
    var bar = document.createElement("nav");
    var segs = [];
    bar.className = "sk-bottomnav";
    bar.setAttribute("aria-label", panels.length === 1
      ? "This training" : "The " + panels.length + " parts of this training");

    /* Joe, 2026-09-22: "on sticky footer let's put QUICK NAVIGATION above the
       three icons". The bar was three unlabelled segments, so what it WAS took
       a tap to find out. aria-hidden because the nav already carries the same
       thing as its accessible name, and a screen reader does not need it twice. */
    var barLabel = document.createElement("span");
    barLabel.className = "sk-nav-label";
    barLabel.setAttribute("aria-hidden", "true");
    barLabel.textContent = "QUICK NAVIGATION";
    bar.appendChild(barLabel);

    panels.forEach(function (panel, i) {
      var acc = panel.querySelector(".sk-acc");
      var wrap = panel.querySelector(".sk-panel-wrap");
      panel.id = panel.id || "sk-part-" + (i + 1);
      wrap.id = panel.id + "-body";
      acc.setAttribute("aria-controls", wrap.id);

      var tab = document.createElement("button");
      tab.className = "sk-tab";
      tab.type = "button";
      tab.setAttribute("role", "tab");
      tab.setAttribute("aria-controls", wrap.id);
      tab.innerHTML = acc.querySelector(".sk-part-num").outerHTML +
                      acc.querySelector(".sk-part-name").outerHTML;
      strip.appendChild(tab);

      var seg = document.createElement("button");
      seg.className = "sk-navseg";
      seg.type = "button";
      seg.setAttribute("aria-controls", wrap.id);
      /* Joe, 2026-09-22: "use the same colored icons to match". The bar carried
         outline SVGs that matched nothing else on the page, while the part
         headers carry an emoji. CLONED from the header rather than listed here
         a second time, so a bar segment cannot end up wearing an emoji its own
         part does not. Falls back to the SVG for any part with no emoji. */
      var emoji = acc.querySelector(".sk-part-icon");
      var segIcon = emoji ? emoji.cloneNode(true) : icon(acc.getAttribute("data-nav-icon"));
      if (segIcon) seg.appendChild(segIcon);
      var segText = document.createElement("span");
      segText.textContent = acc.getAttribute("data-nav") || acc.querySelector(".sk-part-name").textContent;
      seg.appendChild(segText);
      bar.appendChild(seg);
      segs.push(seg);
      seg.addEventListener("click", function () { open(i, true); });

      tab.addEventListener("click", function () { open(i, false); });
      acc.addEventListener("click", function () {
        /* on a phone a second tap on the open part closes it. On desktop one
           panel is always open, because a tab strip with nothing under it is
           not a state anyone meant to reach. */
        open(panel.getAttribute("data-open") === "true" ? -1 : i, true);
      });
    });

    function open(active, fromAcc) {
      panels.forEach(function (panel, i) {
        var on = i === active;
        panel.setAttribute("data-open", on ? "true" : "false");
        panel.querySelector(".sk-acc").setAttribute("aria-expanded", on ? "true" : "false");
        strip.children[i].setAttribute("aria-selected", on ? "true" : "false");
        strip.children[i].setAttribute("tabindex", on ? "0" : "-1");
        /* NOT bar.children[i] - the bar also carries the QUICK NAVIGATION
           label as its first child, so child index and part index disagree. */
        segs[i].setAttribute("aria-current", on ? "true" : "false");
        /* a reveal element inside a closed panel never intersects, so it would
           sit at opacity 0 for good once the panel opened. Opening the panel
           settles its own contents. */
        if (on) {
          panel.querySelectorAll("[data-sk-reveal]").forEach(function (el) {
            el.classList.add("sk-in");
          });
          /* its headers measured zero while it was closed */
          requestAnimationFrame(function () { if (window.__skLevelHeads) window.__skLevelHeads(); });
        }
      });
      if (fromAcc && active >= 0) {
        /* ---- land at the TOP of the part that just opened, ONCE ----
           Joe, 2026-09-22: "the scrolling anchor little janky here". It was,
           and the cause was that this ran TWICE on purpose. The panels animate
           their height over .32s, so the first scroll aimed at the layout
           BEFORE the part above had finished collapsing and a correction fired
           at 380ms to clean up after it. That correction IS the realignment he
           is watching: the page glides, settles, then jumps again.

           A smooth scroll against a document whose height is still changing
           cannot be made accurate, so the animation is taken out of the way
           instead. The height transition is suppressed for this one layout
           pass, the parts snap to their final sizes, and a single smooth scroll
           then runs against a document that is done moving. The reader sees one
           glide, the expand itself being instant under it.

           ⚠️ THE TARGET DIFFERS BY BREAKPOINT, and picking the wrong one fails
           SILENTLY. The obvious anchor is the part's accordion header, and on a
           phone that is right. On desktop .sk-acc is display:none, so its
           getBoundingClientRect() is all zeros, y computes to roughly the
           current scroll position, and the page does not move at all - which is
           exactly what the in-page "learn how to generate leads" buttons did
           (Jess, 2026-09-22: "they don't go back to the top of the page").
           On desktop the tab strip is the right anchor anyway: land there and
           the reader sees which tab is now active as well as its first line. */
        var visible = function (el) {
          return el && el.getClientRects().length > 0;
        };
        tabsRoot.classList.add("sk-nosnap");
        /* forced reflow, deliberately: the parts must reach their final heights
           in THIS frame or the measurement below is the mid-animation layout
           all over again. */
        void tabsRoot.offsetHeight;
        var acc = panels[active].querySelector(".sk-acc");
        var target = visible(acc) ? acc : (visible(strip) ? strip : panels[active]);
        var y = Math.max(0, target.getBoundingClientRect().top + window.scrollY - 12);
        requestAnimationFrame(function () {
          tabsRoot.classList.remove("sk-nosnap");
          if (Math.abs(y - window.scrollY) >= 4) {
            window.scrollTo({ top: y, behavior: "smooth" });
          }
        });
      }
    }

    /* left/right walk the strip, as a tablist should */
    strip.addEventListener("keydown", function (e) {
      var i = [].indexOf.call(strip.children, document.activeElement);
      if (i < 0) return;
      var next = e.key === "ArrowRight" ? i + 1 : e.key === "ArrowLeft" ? i - 1 : -1;
      if (next < 0 || next >= strip.children.length) return;
      e.preventDefault();
      strip.children[next].focus();
      open(next, false);
    });

    document.querySelector(".sk-ftrain").appendChild(bar);

    openPart = open;

    /* ---- deep link ----
       The marketing links hub sends a rep straight to one part: three buttons
       under every funnel link, "how does this funnel work", "how do I generate
       leads", "what do I say". They all land on THIS page and differ only by
       the hash, so the hub needs no knowledge of the page beyond its url.
       Anything unparseable falls through to part 1 rather than to nothing. */
    function fromHash() {
      var m = /^#part-([1-9]\d*)$/.exec(window.location.hash || "");
      var i = m ? parseInt(m[1], 10) - 1 : 0;
      return i >= 0 && i < panels.length ? i : 0;
    }
    /* ---- what is open when the page loads ----
       On a phone: NOTHING. The first screen is then the three numbered rows,
       so the reader can see at a glance that the training has three parts and
       what each one is. Opening part 1 by default filled the whole screen with
       part 1 and gave no hint that 2 and 3 existed below it, which is the one
       thing this page cannot afford. On desktop the strip already says "three
       parts", so a panel stays open there. A deep link from the hub always
       wins over both, since the rep asked for that part by name. */
    /* A ONE-PART page (What I Do, Linktree, the DROPS one pager) has no strip
       and no bottom bar, so the phone test below would read its hidden strip as
       "this is a phone" and open nothing at all, on every width. There is also
       nothing to choose between: the single part IS the page, so it is open. */
    var single = panels.length === 1;
    var deepLinked = /^#part-([1-9]\d*)$/.test(window.location.hash || "");
    var phone = !single && getComputedStyle(strip).display === "none";
    open(single || deepLinked || !phone ? fromHash() : -1, false);
    window.addEventListener("hashchange", function () { open(fromHash(), true); });
  }

  /* an in-prose control that jumps to another part, e.g. part 1 pointing at the
     follow-up scripts in part 3 */
  document.querySelectorAll("[data-goto-part]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      var i = parseInt(btn.getAttribute("data-goto-part"), 10) - 1;
      if (openPart && i >= 0) openPart(i, true);
    });
  });


  /* ---- level 2: the video row ----
     Same component, one level down. On desktop the headers are inert and every
     item is open, so the row reads as three columns; the CSS decides which mode
     is live and the JS just asks it, so the breakpoint stays in one place. */
  document.querySelectorAll("[data-acc]").forEach(function (group) {
    var items = [].slice.call(group.querySelectorAll(".sk-vid-item"));
    items.forEach(function (item, i) {
      var head = item.querySelector(".sk-vid-head");
      if (!head) return;
      var wrap = item.querySelector(".sk-vid-wrap");
      wrap.id = wrap.id || "sk-vid-" + (i + 1) + "-" + Math.round(i * 7 + items.length);
      head.setAttribute("aria-controls", wrap.id);
      head.addEventListener("click", function () {
        /* inert on desktop: the chevron is hidden there, which is the same
           signal the reader gets */
        if (getComputedStyle(item.querySelector(".sk-chev")).display === "none") return;
        var wasOpen = item.getAttribute("data-open") === "true";
        items.forEach(function (other) {
          var on = other === item && !wasOpen;
          other.setAttribute("data-open", on ? "true" : "false");
          var h = other.querySelector(".sk-vid-head");
          if (h) h.setAttribute("aria-expanded", on ? "true" : "false");
        });
      });
    });
  });

  /* ---- the strategy write-up disclosure, one per video card ----
     Independent of its neighbours: there is exactly one per card, and a rep
     comparing two strategies should be able to have both open. */
  document.querySelectorAll("[data-read]").forEach(function (box, i) {
    var head = box.querySelector(".sk-read-head");
    var wrap = box.querySelector(".sk-read-wrap");
    if (!head || !wrap) return;
    wrap.id = wrap.id || "sk-read-" + (i + 1);
    head.setAttribute("aria-controls", wrap.id);
    var label = head.querySelector("[data-read-label]");
    head.addEventListener("click", function () {
      var on = box.getAttribute("data-open") !== "true";
      box.setAttribute("data-open", on ? "true" : "false");
      head.setAttribute("aria-expanded", on ? "true" : "false");
      /* the label states the action available NOW, not the current state */
      if (label) label.textContent = on ? "Read less" : "Read more";
    });
  });

  /* ---- level the video-card headers ----
     The three frames must start on the same line, and CSS alone cannot do it:
     .sk-vids is a grid of independent columns, and the frame sits two levels
     down inside .sk-vid-wrap, so subgrid would need the card flattened first.

     A hand-set min-height was the stopgap and it broke THREE times: when the
     copy changed, when the READ MORE label was added, and when the content
     column narrowed to 880. It is tuned to the longest title and nothing tells
     you when the copy outgrows it, so it fails silently and looks fine to
     whoever made the change. Measuring at runtime cannot go stale. */
  function levelHeads() {
    document.querySelectorAll(".sk-vids").forEach(function (row) {
      var heads = [].slice.call(row.querySelectorAll(".sk-vid-head"));
      if (heads.length < 2) return;
      heads.forEach(function (h) { h.style.minHeight = ""; });
      /* only when the cards are actually side by side. On a phone each one is
         full width and a shared height would just pad the short ones. */
      if (getComputedStyle(row).gridTemplateColumns.split(" ").length < 2) return;
      /* a closed panel measures zero, so leave it alone and level it on open */
      var tallest = 0;
      heads.forEach(function (h) { tallest = Math.max(tallest, h.getBoundingClientRect().height); });
      if (!tallest) return;
      heads.forEach(function (h) { h.style.minHeight = Math.ceil(tallest) + "px"; });
    });
  }
  window.__skLevelHeads = levelHeads;
  levelHeads();
  window.addEventListener("resize", levelHeads);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(levelHeads);


  /* ---- click-to-load video facade ----
     The poster ships in a data attribute and the player is only injected on
     click, so a page carrying five videos costs nothing until a rep asks. */
  function paint(frame) {
    var p = frame.getAttribute("data-poster");
    if (p) frame.style.backgroundImage = "url(" + p + ")";
  }
  function play(frame) {
    if (frame.getAttribute("data-playing") === "true") return;
    var id = frame.getAttribute("data-vimeo");
    if (!id) return;
    var f = document.createElement("iframe");
    f.src = "https://player.vimeo.com/video/" + encodeURIComponent(id) +
            "?autoplay=1&title=0&byline=0&portrait=0&dnt=1";
    f.setAttribute("allow", "autoplay; fullscreen; picture-in-picture");
    f.setAttribute("allowfullscreen", "");
    f.setAttribute("title", frame.getAttribute("aria-label") || "Training video");
    frame.appendChild(f);
    frame.setAttribute("data-playing", "true");
  }
  document.querySelectorAll(".sk-frame[data-vimeo]").forEach(function (frame) {
    paint(frame);
    frame.addEventListener("click", function () { play(frame); });
    frame.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); play(frame); }
    });
  });

  /* scroll reveal, same contract as _shared/shark-reveal */
  var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (!reduce && "IntersectionObserver" in window) {
    document.documentElement.classList.add("sk-motion");
    document.querySelectorAll("[data-sk-stagger]").forEach(function (g) {
      g.querySelectorAll("[data-sk-reveal]").forEach(function (el, n) {
        el.style.setProperty("--sk-i", n);
      });
    });
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) { e.target.classList.add("sk-in"); io.unobserve(e.target); }
      });
    }, { rootMargin: "0px 0px -8% 0px", threshold: 0.08 });
    document.querySelectorAll("[data-sk-reveal]").forEach(function (el) { io.observe(el); });
  }
})();

}
